                                   dht->used,
                                   name.ptr, (int)name.len, value.ptr, (int)value.len);
        }

        if (ret >= list_size) {
                ret = -HPACK_ERR_TOO_LARGE;
                goto leave;
        }

        /* put an end marker */
        list[ret].n = list[ret].v = IST_NULL;
        ret++;

 leave:
        hpack_debug_printf("-- done: ret=%d list_size=%d --\n", (int)ret, (int)list_size);
        return ret;
